import { renderHook, act, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { useBooks } from './useBooks';
import * as api from '../api';

describe('useBooks', () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('starts in loading state with no data and no error', () => {
    const { result } = renderHook(() => useBooks());

    expect(result.current.loading).toBe(true);
    expect(result.current.data).toBeUndefined();
    expect(result.current.error).toBeUndefined();
  });

  it('resolves to data after getBooks settles', async () => {
    const { result } = renderHook(() => useBooks());

    await waitFor(() => expect(result.current.loading).toBe(false));

    expect(result.current.data).toBeDefined();
    expect(Array.isArray(result.current.data)).toBe(true);
    expect(result.current.error).toBeUndefined();
  });

  it('data matches what getBooks returns', async () => {
    const books = api.getBooks();
    const { result } = renderHook(() => useBooks());

    await waitFor(() => expect(result.current.loading).toBe(false));

    expect(result.current.data).toEqual(books);
  });

  it('transitions from loading=true to loading=false on success', async () => {
    const { result } = renderHook(() => useBooks());

    expect(result.current.loading).toBe(true);

    await waitFor(() => expect(result.current.loading).toBe(false));

    expect(result.current.loading).toBe(false);
    expect(result.current.data).toBeDefined();
  });

