import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi } from 'vitest';
import { BookCard } from './BookCard';
import type { Book } from '../../types';

const book: Book = {
  id: 'book-1',
  title: 'The Great Gatsby',
  author: 'F. Scott Fitzgerald',
  status: 'available',
};

describe('BookCard', () => {
  it('renders title', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByRole('heading', { name: 'The Great Gatsby' })).toBeInTheDocument();
  });

  it('renders author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText('F. Scott Fitzgerald')).toBeInTheDocument();
  });

  it('renders status badge with the book status text', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(screen.getByText('available')).toBeInTheDocument();
  });

  it('status badge carries data-status attribute matching the status', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    const badge = screen.getByText('available');
    expect(badge).toHaveAttribute('data-status', 'available');
  });

  it('renders different status values on the badge', () => {
    const borrowed: Book = { ...book, status: 'borrowed' };
    render(<BookCard book={borrowed} onClick={vi.fn()} />);
    const badge = screen.getByText('borrowed');
    expect(badge).toHaveAttribute('data-status', 'borrowed');
  });

  it('has an accessible label combining title and author', () => {
    render(<BookCard book={book} onClick={vi.fn()} />);
    expect(
      screen.getByRole('button', { name: 'The Great Gatsby by F. Scott Fitzgerald' })
    ).toBeInTheDocument();
  });

  it('calls onClick with the book id when clicked', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    await userEvent.click(screen.getByRole('button', { name: /The Great Gatsby/ }));
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith('book-1');
  });

  it('calls onClick with the book id when Enter is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    const card = screen.getByRole('button', { name: /The Great Gatsby/ });
    card.focus();
    await userEvent.keyboard('{Enter}');
    expect(handleClick).toHaveBeenCalledOnce();
    expect(handleClick).toHaveBeenCalledWith('book-1');
  });

  it('does not call onClick when a non-Enter key is pressed', async () => {
    const handleClick = vi.fn();
    render(<BookCard book={book} onClick={handleClick} />);
    const card = screen.getByRole('button', { name: /The Great Gatsby/ });
